    var txt = SVG('#dist-' + k);
    if (txt) txt.text(fmt(st.dist && st.dist[k]));
  });

  annotationG.text(st.stage || '').font({ family: 'serif', size: 30, anchor: 'middle' }).center(450, 582).fill('#000');
  annotationG.text('pass ' + (st.pass || 0) + ' / 4     changes this pass: ' + (st.changes || 0))
    .font({ family: 'sans-serif', size: 17, anchor: 'middle' }).center(450, 33).fill('#333');

  if (st.edge) {
    var e = st.edge, a = V[e.u], b = V[e.v];
    var mx = (a.x + b.x) / 2, my = (a.y + b.y) / 2;
    if (edgeKey(e.u, e.v) === 't->x') my -= 62;
    if (edgeKey(e.u, e.v) === 'x->t') my += 60;
    var note = 'd[' + e.u + '] + ' + e.w + ' = ' + valText(st.candidate);
    if (st.message) note += '   ' + st.message;
    var bg = annotationG.rect(Math.min(490, note.length * 8 + 18), 28).center(Math.max(255, Math.min(650, mx)), Math.max(68, Math.min(548, my - 38))).fill('#fff').opacity(0.86).stroke({ color: '#bbb', width: 1 });
    annotationG.text(note).font({ family: 'sans-serif', size: 15, anchor: 'middle' }).center(bg.cx(), bg.cy() + 1).fill('#111');
  }
}

function renderGuided(i) {
  demoIndex = Math.max(0, Math.min(guidedSteps.length - 1, i));
  stopReplay();
  var step = guidedSteps[demoIndex];
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (demoIndex + 1) + ' / ' + guidedSteps.length;
  renderState(step.state);
}

function prevStep() { renderGuided(demoIndex - 1); }
function nextStep() { renderGuided(demoIndex + 1); }
window.prevStep = prevStep;
window.nextStep = nextStep;

function frameToState(fr) {
  var s = fr.state || {};
  var st = {
    dist: s.dist || { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity },
    pred: s.pred || {},
    pass: s.pass || 0,
    changes: s.changes || 0,
    stage: 'replay',
    highlights: [],
    message: fr.message || '',
    candidate: fr.candidate,
    edge: fr.edge
  };
  if (fr.edge) st.highlights = [[fr.edge.u, fr.edge.v]];
  if (fr.badVertices) st.badVertices = fr.badVertices;
  return st;
}

function showReplayFrame(i) {
  if (!replayFrames.length) return;
  replayIndex = Math.max(0, Math.min(replayFrames.length - 1, i));
  var fr = replayFrames[replayIndex];
  renderState(frameToState(fr));
  document.getElementById('relaxCounter').textContent = (replayIndex + 1) + ' of ' + replayFrames.length;
  document.getElementById('relaxCaption').textContent = fr.message || fr.kind || '';
  var start = Math.max(0, replayIndex - 8);
  document.getElementById('relaxLog').value = replayFrames.slice(start, replayIndex + 1).map(function(f, j) {
    return (start + j + 1) + '. ' + (f.message || f.kind || '');
  }).join('\n');
}
function relaxFirst() { stopReplay(); showReplayFrame(0); }
function relaxPrev() { stopReplay(); showReplayFrame(replayIndex - 1); }
function relaxNext() { stopReplay(); showReplayFrame(replayIndex + 1); }
function stopReplay() {
  if (replayTimer) clearInterval(replayTimer);
  replayTimer = null;
  var b = document.getElementById('relaxPlayBtn');
  if (b) b.textContent = '▶';
}
function relaxPlayPause() {
  if (!replayFrames.length) return;
  if (replayTimer) { stopReplay(); return; }
  document.getElementById('relaxPlayBtn').textContent = '❚❚';
  var speed = +document.getElementById('relaxSpeedInput').value || 1;
  replayTimer = setInterval(function() {
    if (replayIndex >= replayFrames.length - 1) { stopReplay(); return; }
    showReplayFrame(replayIndex + 1);
  }, 650 / speed);
}
window.relaxFirst = relaxFirst;
window.relaxPrev = relaxPrev;
window.relaxNext = relaxNext;
window.relaxPlayPause = relaxPlayPause;

var samples = {
  sample: document.getElementById('relaxEditorCode').value,
  buggy: 'function relax(u, v, w) {\n  const candidate = dist(u) + w;\n  // BUG: comparison is reversed, so improvements are ignored.\n  if (less(dist(v), candidate)) {\n    mark(u, v, "wrongly relaxed");\n    setDist(v, candidate);\n    setPred(v, u);\n  } else {\n    mark(u, v, "no change");\n  }\n}',
  starter: 'function relax(u, v, w) {\n  const candidate = dist(u) + w;\n  // TODO: if candidate improves d[v], update d[v] and pred[v].\n  mark(u, v, "inspected");\n}'
};
function loadRelaxSample(which) {
  document.getElementById('relaxEditorCode').value = samples[which] || samples.sample;
}
window.loadRelaxSample = loadRelaxSample;

function checkSuccess(frames) {
  if (!frames.length) return { ok: false, bad: vertexOrder.slice(), msg: 'No frames were recorded.' };
  var last = frames[frames.length - 1].state || {};
  var d = last.dist || {}, p = last.pred || {};
  var expD = { s: 0, t: 2, x: 4, y: 7, z: -2 };
  var expP = { y: 's', x: 'y', t: 'x', z: 't' };
  var bad = [];
  vertexOrder.forEach(function(k) { if (d[k] !== expD[k]) bad.push(k); });
  Object.keys(expP).forEach(function(k) { if (p[k] !== expP[k] && bad.indexOf(k) < 0) bad.push(k); });
  return {
    ok: bad.length === 0,
    bad: bad,
    msg: bad.length === 0 ? 'correct: estimates and predecessor tree match s → y → x → t → z' : 'wrong answer: check ' + bad.join(', ')
  };
}

function makeErrorFrame(msg) {
  return {
    kind: 'error',
    message: msg,
    state: { dist: { s: 0, t: Infinity, x: Infinity, y: Infinity, z: Infinity }, pred: {}, pass: 0, changes: 0 }
  };
}

function runRelaxEditor() {
  stopReplay();
  var btn = document.getElementById('relaxRunBtn');
  btn.disabled = true;
  document.getElementById('relaxStatus').textContent = 'running...';
  document.getElementById('relaxCaption').textContent = '';
  document.getElementById('relaxLog').value = '';
  var code = document.getElementById('relaxEditorCode').value;

  var workerSrc = `
  const vertices = ['s','t','x','y','z'];
  const edges = [
    {u:'t',v:'x',w:5},{u:'t',v:'y',w:8},{u:'t',v:'z',w:-4},{u:'x',v:'t',w:-2},
    {u:'y',v:'x',w:-3},{u:'y',v:'z',w:9},{u:'z',v:'x',w:7},{u:'z',v:'s',w:2},
    {u:'s',v:'t',w:6},{u:'s',v:'y',w:7}
  ];
  onmessage = function(ev) {
    const code = ev.data.code;
    let D = {s:0,t:Infinity,x:Infinity,y:Infinity,z:Infinity};
    let P = {};
    let pass = 0, changes = 0, currentEdge = null, opCount = 0;
    const frames = [];
    const maxOps = 5000, maxFrames = 1000, start = Date.now();
    function cloneState(){ return {dist:{s:D.s,t:D.t,x:D.x,y:D.y,z:D.z}, pred:Object.assign({},P), pass:pass, changes:changes}; }
    function val(v){ return v===Infinity ? 'Infinity' : String(v); }
    function checkCap(){
      opCount++;
      if (opCount > maxOps) throw new Error('operation cap hit: possible infinite or overly chatty relaxation');
      if (frames.length >= maxFrames) throw new Error('frame cap hit: too many recorded steps');
      if (Date.now() - start > 1600) throw new Error('timeout while running relaxation');
    }
    function vertex(v){
      if (vertices.indexOf(v) < 0) throw new Error('unknown vertex "' + v + '"');
    }
    function record(kind, indices, message, extra){
      checkCap();
      frames.push(Object.assign({kind:kind, state:cloneState(), indices:indices||[], edge:currentEdge, message:message||kind}, extra||{}));
    }
    function dist(v){
      vertex(v);
      record('dist',[v],'read d['+v+'] = '+val(D[v]));
      return D[v];
    }
    function less(a,b){
      record('less',[],'compare '+val(a)+' < '+val(b)+' → '+(a < b));
      return a < b;
    }
    function setDist(v,value){
      vertex(v);
      D[v] = value;
      changes++;
      record('setDist',[v],'set d['+v+'] = '+val(value));
    }
    function setPred(v,u){
      vertex(v); vertex(u);
      P[v] = u;
      record('setPred',[u,v],'set predecessor of '+v+' to '+u);
    }
    function mark(u,v,note){
      vertex(u); vertex(v);
      currentEdge = edges.find(e => e.u===u && e.v===v) || {u:u,v:v,w:0};
      const cand = D[u] === Infinity ? Infinity : D[u] + currentEdge.w;
      record('mark',[u,v], (u+' → '+v+': '+(note || 'marked')), {edge:currentEdge, candidate:cand});
    }
    const api = Object.freeze({dist, less, setDist, setPred, mark});
    try {
      let relax = (new Function('dist','less','setDist','setPred','mark','api', code + '\\n; if (typeof relax !== "function") throw new Error("missing entry point: define function relax(u, v, w)"); return relax;'))(dist, less, setDist, setPred, mark, api);
      record('start',[],'start Bellman-Ford with d[s]=0 and all other distances Infinity');
      for (pass = 1; pass <= 4; pass++) {
        changes = 0;
        record('passStart',[],'begin pass '+pass+' of 4');
        for (const e of edges) {
          currentEdge = e;
          record('inspect',[e.u,e.v],'inspect edge '+e.u+' → '+e.v+' (weight '+e.w+')', {edge:e, candidate:D[e.u]===Infinity?Infinity:D[e.u]+e.w});
          relax(e.u, e.v, e.w);
        }
        record('passEnd',[],'end pass '+pass+' with '+changes+' distance change(s)');
      }
      postMessage({ok:true, frames:frames});
    } catch (err) {
      frames.push({kind:'error', state:cloneState(), message:'error: '+(err && err.message ? err.message : err)});
      postMessage({ok:false, frames:frames, error:(err && err.message ? err.message : String(err))});
    }
  };`;
  var blob = new Blob([workerSrc], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  var worker = new Worker(url);
  var finished = false;
  var timer = setTimeout(function() {
    if (finished) return;
    finished = true;
    worker.terminate();
    URL.revokeObjectURL(url);
    btn.disabled = false;
    replayFrames = [makeErrorFrame('timeout: code took too long to finish')];
    document.getElementById('relaxStatus').textContent = 'error';
    showReplayFrame(0);
  }, 2100);

  worker.onmessage = function(ev) {
    if (finished) return;
    finished = true;
    clearTimeout(timer);
    worker.terminate();
    URL.revokeObjectURL(url);
    btn.disabled = false;
    replayFrames = ev.data.frames && ev.data.frames.length ? ev.data.frames : [makeErrorFrame('No frames were recorded.')];
    var result = checkSuccess(replayFrames);
    replayFrames.push({
      kind: result.ok ? 'success' : 'wrong',
      message: result.msg,
      badVertices: result.bad,
      state: replayFrames[replayFrames.length - 1].state
    });
    document.getElementById('relaxStatus').textContent = ev.data.ok ? (result.ok ? 'correct' : 'wrong answer') : 'error';
    showReplayFrame(0);
  };
  worker.onerror = function(e) {
    if (finished) return;
    finished = true;
    clearTimeout(timer);
    worker.terminate();
    URL.revokeObjectURL(url);
    btn.disabled = false;
    replayFrames = [makeErrorFrame('worker error: ' + (e.message || 'failed to run'))];
    document.getElementById('relaxStatus').textContent = 'error';
    showReplayFrame(0);
  };
  worker.postMessage({ code: code });
}
window.runRelaxEditor = runRelaxEditor;

renderGuided(0);
window.__markRendered();
